import math
fn putd(mut o &u8,p int,x f64){bits:=u64(math.bits_from_f64(x));for k in 0..8{unsafe{o[p+k]=u8(bits&255)};bits>>=8}}
@[export:'fuzzy_operations']
pub fn fuzzy_operations(v &i64,n usize,o &u8,cap usize)i64{if isnil(v)||n!=8{return -1};op:=unsafe{v[0]};if op<0||op>3{return -1};for i in 1..8{x:=unsafe{v[i]};if x<0||x>1000{return -1}};if op==0{for i in 4..8{if unsafe{v[i]!=0}{return -1}}}else if op==1||op==2{if unsafe{v[7]!=0}{return -1}}else{if unsafe{v[4]!=0||v[5]!=0||v[6]!=0||v[1]>=v[2]||v[2]>=v[3]}{return -1}};size:=if op==3{8}else{24};if isnil(o)||cap<size{return -2};a:=f64(unsafe{v[1]})/1000.;b:=f64(unsafe{v[2]})/1000.;c:=f64(unsafe{v[3]})/1000.;match op{0{putd(mut o,0,1-c);putd(mut o,8,1-a);putd(mut o,16,1-b)}1{putd(mut o,0,math.max(a,f64(unsafe{v[4]})/1000.));putd(mut o,8,math.min(c,f64(unsafe{v[6]})/1000.));putd(mut o,16,(b+f64(unsafe{v[5]})/1000.)/2)}2{putd(mut o,0,math.min(a,f64(unsafe{v[4]})/1000.));putd(mut o,8,(b+f64(unsafe{v[5]})/1000.)/2);putd(mut o,16,math.max(c,f64(unsafe{v[6]})/1000.))}else{x:=f64(unsafe{v[7]})/1000.;y:=if x<=a||x>=c{0.0}else if x<=b{(x-a)/(b-a)}else{(c-x)/(c-b)};putd(mut o,0,y)}};size}
